{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "protocol",
      "alternatives": [
        "(df['PROTOCOL'] == 6) | ((df['TCP_FLAGS'] == 0) & (df['CLIENT_TCP_FLAGS'] == 0) & (df['SERVER_TCP_FLAGS'] == 0))"
      ],
      "features": ["TCP_FLAGS", "CLIENT_TCP_FLAGS", "SERVER_TCP_FLAGS"],
      "rationale": "TCP flag fields are only meaningful for TCP flows (PROTOCOL=6), so they must be zero for non-TCP flows."
    },
    {
      "id": "R2",
      "category": "protocol",
      "alternatives": [
        "(df['PROTOCOL'] == 6) | ((df['RETRANSMITTED_IN_BYTES'] == 0) & (df['RETRANSMITTED_IN_PKTS'] == 0) & (df['RETRANSMITTED_OUT_BYTES'] == 0) & (df['RETRANSMITTED_OUT_PKTS'] == 0))"
      ],
      "features": ["RETRANSMITTED_IN_BYTES", "RETRANSMITTED_IN_PKTS", "RETRANSMITTED_OUT_BYTES", "RETRANSMITTED_OUT_PKTS"],
      "rationale": "Retransmission counters are TCP-specific and must be zero for non-TCP flows."
    },
    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "(df['PROTOCOL'] == 6) | ((df['TCP_WIN_MAX_IN'] == 0) & (df['TCP_WIN_MAX_OUT'] == 0))"
      ],
      "features": ["TCP_WIN_MAX_IN", "TCP_WIN_MAX_OUT"],
      "rationale": "TCP window maximums are only defined for TCP flows, so they must be zero for non-TCP flows."
    },
    {
      "id": "R4",
      "category": "protocol",
      "alternatives": [
        "(df['PROTOCOL'] == 1) | ((df['ICMP_TYPE'] == 0) & (df['ICMP_IPV4_TYPE'] == 0))"
      ],
      "features": ["ICMP_TYPE", "ICMP_IPV4_TYPE"],
      "rationale": "ICMP fields are only meaningful for ICMP flows (PROTOCOL=1), so they must be zero for non-ICMP flows."
    }
  ]
}
